"""Build the bounded sky sampling/material/Blueprint contract from retained evidence."""
import importlib.util,pathlib,math,json
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=ROOT/'research/world-recovery/sky-recovery'
spec=importlib.util.spec_from_file_location('g',ROOT/'tools/asset-pipeline/export-world.py');g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
spec=importlib.util.spec_from_file_location('shader_eval',ROOT/'tools/asset-pipeline/restore-evidenced-shaders.py');ev=importlib.util.module_from_spec(spec);spec.loader.exec_module(ev)
idx=g.READ(OUT/'index.json');u=g.READ(OUT/'uniforms.json');mats=g.READ(OUT/'material-descriptors.json');key='/Game/-HeroGame/Maps/SubLevel/LightingTest#export:14';mat=mats[key];sampling=g.READ(OUT/'sampling-evidence.json');bp=g.READ(OUT/'blueprint-evidence.json')
vectors=[ev.evaluate(u,h,mat) for h in u['uniformVectorPreshaders']];scalars=[ev.evaluate(u,h,mat) for h in u['uniformScalarPreshaders']]
s=idx['shaders'][0];assert {'constantBuffer':3,'resourceIndex':0,'bindIndex':12} in s['resourceTable']['textureBindings'];assert {'constantBuffer':3,'resourceIndex':1,'bindIndex':3} in s['resourceTable']['samplerBindings'];asm=pathlib.Path(s['assemblyFile']).read_text();assert 'dcl_resource_texture2d (float,float,float,float) t12' in asm and 'mul r2.xy, v2.xyxx, l(1.000000, 2.000000' in asm
world=g.READ(g.OUT/'geometry-manifest.json');obj=next(o for l in world['levels'] for o in l['objects'] if o['id']=='LightingTest:22');angle=math.degrees(2*math.atan2(-obj['rotation'][1],obj['rotation'][3]));assert abs(angle-35)<.001
contract={'schemaVersion':1,'status':'original-sampling-and-emission-recovered; full-original-view-compositing-not-recovered','sourceMaterial':key,'baseMaterial':'/Game/Skies/Materials/M_Skies_Master','meshObject':obj,'sampling':{'textureType':'Texture2D','parameterName':'HDRI_Cubemap','sourceTexture':'/Game/Skies/Textures/T_SkyCloudy11','textureUrl':sampling['image']['url'],'width':8192,'height':2048,'hdrEncoding':'flat RGBE payload after byte 51; original HDR header -Y 2048 +X 8192','colorSpace':'linear, original SRGB=false; never apply sRGB decoding to this data','coordinateFormula':'uvSample = vec2(originalMeshUV0.x, 2.0 * originalMeshUV0.y)','usesWorldDirection':False,'usesCameraDirection':False,'rowConvention':'preserve source top-to-bottom rows; shader v=0 addresses source top row; apply any API upload inversion exactly once to realize this, not a guessed panorama flip','wrapMode':'Texture address modes absent in serialized Texture2D properties; UE class-default wrap inferred, not an explicitly serialized override','filtering':'original PS SampleBias with View.MaterialTextureMipBias; original texture has 14 mips. Single-level RGBE file only preserves top mip. Web mip/filter selection is a boundary.','axisUVReference':'sampling-evidence.json#/mesh/axisUVSamples'},'formula':{'sample':'h = texture2D(HDRI_Cubemap, uvSample).rgb (linear HDR)','contrast':'p = componentwise(h > 0 ? exp2(log2(h) * HDRI_Contrast) : 0)','emissive':'c = p * HDRI_Brightness * HDRI_Tint.rgb; emissive = max(mix(c, SelectionColor.rgb, SelectionColor.a), 0)','opacity':'alpha = clamp(Opacity, 0, 1)','noUpperClamp':'Original emissive preserves HDR values above 1; do not clamp or tone-map the texture before applying the material.','fullPixelBoundary':'Original PS additionally contains view fog, lighting/debug paths and pre-exposure cb0[135].y; this contract covers original texture/emissive/opacity, not full original renderer output.'},'effectiveParameters':{'HDRI_Contrast':scalars[0]['value'][0],'HDRI_Brightness':scalars[1]['value'][0],'HDRI_Tint':vectors[2]['value'][:3],'SelectionColor':vectors[0]['value'],'Opacity':scalars[3]['value'][0]},'bindings':{'pixelShader':s,'materialConstantBuffer':3,'textureRegister':12,'samplerRegister':3,'emissiveTextureDimension':'texture2d','vectorRegisters':vectors,'scalarRegisters':[dict(x,register=4+i//4,component='xyzw'[i%4]) for i,x in enumerate(scalars)],'sourceMaterialProperty':'M_Skies_Master Exports/0/Data/0 is EmissiveColor with original expression MaterialExpressionMultiply_4'},'blueprint':{'sourcePackage':'/Game/Skies/Blueprints/BP_Sky','sourceSha256':bp['sha256'],'construction':{'functionExport':4,'actions':['SetVisibility(IsSkyDomeVisibility,false)','SetWorldRotation(0,0,0)','CreateDynamicMaterialInstance(MI_Skies); SetMaterial(slot 0, dynamic instance)','Set HDRI_Brightness = actor.HDRI_Brightness * actor.GlobalBrightness','Set HDRI_Tint and HDRI_Cubemap from actor properties','MakeRotator(0,0,HDRI_Rotation); SetWorldRotation','Set HDRI_Contrast from actor property'],'lightingTestHDRIRotationDegrees':35,'geometryAlreadyContainsRotation':True,'worldQuaternionMatchesYaw35MaximumAngleErrorDegrees':abs(angle-35),'avoidDoubleRotation':'Use original world transform; do not add another 35-degree shader rotation.'},'beginPlay':{'entryPoint':214,'actions':['WeatherIndex = RandomIntegerInRange(0,1)','SetActorTickEnabled(true)']},'tick':{'entryPoint':295,'actions':['DeltaTime = DeltaSeconds','target = WeatherIndex==0 ? 1 : 0','WeatherOpacity = Ease(WeatherOpacity,target,DeltaTime*ChangeSpeed, easingEnum=0, BlendExp=2, Steps=2)','WeatherChangeCounter += DeltaTime','if WeatherChangeCounter>=ChangeInterval: choose new random WeatherIndex 0..1; reset WeatherChangeCounter=0','else: HDRI_MInst.SetScalarParameterValue(Opacity,WeatherOpacity)'],'lightingTestChangeSpeed':0.07000000029802322,'lightingTestChangeIntervalSeconds':30,'defaultWeatherOpacity':1,'runtimeRandomSequenceObserved':False},'cameraAndRotation':'No camera position lookup, camera following, or per-tick rotation call in these exact BP_Sky functions. HDRI_RotationSpeed appears in NameMap but is not used by recovered function AST; do not infer automatic sky rotation from that name.','staticVsRuntime':'Cooked material snapshot Opacity=1; original BeginPlay/Tick can fade it. Construction/Tick functions were decoded, not executed.'},'verification':{'validatedDXBCShaders':len(idx['shaders']),'unresolvedDXBCLiterals':len(idx['unresolvedDxbcLiterals']),'originalFloat16ToRGBEExactSamples':sampling['originalPixelValidation']['exactlyMatchedSamples'],'sourceUVRange':[sampling['mesh']['uv0Min'],sampling['mesh']['uv0Max']],'materialPackageUnmodified':True,'sourceGameNotExecuted':True},'files':{name:{'sha256':g.HASH(OUT/name)} for name in ['index.json','uniforms.json','sampling-evidence.json','blueprint-evidence.json','UEViewer-ExportTexture.cpp']}}
g.WRITE(OUT/'contract.json',contract);print(json.dumps({'parameters':contract['effectiveParameters'],'verification':contract['verification'],'yawError':abs(angle-35)}))
parameters=contract['effectiveParameters']
g.WRITE(g.OUT/'sky-material-manifest.json',{'schemaVersion':1,'materials':{key:{'texture':{'url':sampling['image']['url'],'colorSpace':'linear','texCoord':0},'uvScale':[1,2],'contrast':parameters['HDRI_Contrast'],'brightness':parameters['HDRI_Brightness'],'tint':parameters['HDRI_Tint'],'selectionColor':parameters['SelectionColor'],'opacity':parameters['Opacity'],'source':{'baseMaterial':contract['baseMaterial'],'instance':key,'objectId':'LightingTest:22','texturePackage':contract['sampling']['sourceTexture'],'contract':'research/world-recovery/sky-recovery/contract.json','contractSha256':g.HASH(OUT/'contract.json'),'shaderSha256':s['sha256'],'textureSha256':sampling['image']['sha256']},'semantics':{'sourceOutput':'EmissiveColor','blendMode':'translucent','originalPixelContainsLighting':True,'originalEmissiveAllowsValuesAboveOne':True,'worldRotationAlreadyInGeometry':True,'sourceTopRowAtV0':True,'runtimeWeatherOpacityApplied':False},'limitations':['Only the evidenced LightingTest embedded material instance is included.','Original lighting/fog/pre-exposure residual is outside this sampling/emission recovery.','Snapshot opacity=1; original BP can change it over time.','HDR export retains top mip with RGBE quantization; original source has 14 mip levels.']}}})
